            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

public sealed class IssuerSerial
{
    /// <summary>ASN.1 alias GeneralNames ::= SEQUENCE OF GeneralName.</summary>
    public Asn1Kit.Pkix.GeneralName[] Issuer { get; set; } = Array.Empty<Asn1Kit.Pkix.GeneralName>();
    /// <summary>ASN.1 alias CertificateSerialNumber ::= INTEGER.</summary>
    public Asn1Integer SerialNumber { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        writer.WriteSequence(tag, inner =>
        {
            inner.WriteSequenceOf(Asn1Tag.Sequence, Issuer, static (inner, item) =>
            {
                item.Encode(inner);
            });
            inner.WriteInteger(Asn1Tag.Integer, SerialNumber);
        });
    }

    public static IssuerSerial Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static IssuerSerial Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new IssuerSerial();
            value.Issuer = reader.ReadSequenceOf(Asn1Tag.Sequence, static inner => Asn1Kit.Pkix.GeneralName.Decode(inner));
            value.SerialNumber = reader.ReadIntegerValue(Asn1Tag.Integer);
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

